   let '(loop_i_upper) := 31 in
   (foreach_Z_up loop_i_lower loop_i_upper 1 equal
     (fun i equal => andb (equal) ((eq_vec ((vec_access_dec (a) (i))) ((vec_access_dec (b) (i))))))).

