                Withdrawal_validator_index := (Build_protocol_quantity (w__1));
                Withdrawal_address := w__2;
                Withdrawal_amount := (Build_protocol_quantity (w__3)) |})).

Definition EMPTY_EXECUTION_REQUESTS : ExecutionRequests :=
