   (ssz_field_offset (offset) (8)) >>= fun (w__0 : byte_quantity) =>
   (ssz_limb (input) (w__0)) >>= fun c1 =>
   (ssz_field_offset (offset) (16)) >>= fun (w__1 : byte_quantity) =>
   (ssz_limb (input) (w__1)) >>= fun c2 =>
   (ssz_field_offset (offset) (24)) >>= fun (w__2 : byte_quantity) =>
