    : M (byte_quantity).

Definition rlp_string_size (len : byte_quantity) (first : mword 8) : M (byte_length) :=
   (if andb ((byte_quantity_equal (len) (BYTE_ONE)))
         ((eq_vec ((access_vec_dec (first) (7))) (('b"0")))) then
