Definition rlp_write_raw_bytes (data : list (mword 8)) (len : byte_quantity) : M (unit) :=
   (scratch_push_bytes (data) (len))  : M (unit).

Definition rlp_write_raw_slice (data : ByteSlice) : M (unit) :=
