    : M (unit).

Definition rlp_write_uint_word (w : mword 256) : M (unit) :=
   let '((bytes, len)) := minimal_word_bytes (w) in
   (rlp_write_bytes (bytes) ((ByteQuantity (len))))
    : M (unit).

Definition rlp_write_protocol_quantity (n : protocol_quantity) (*(0 <=? n) && (n <=? (2 ^ 64 - 1))*)
: M (unit) :=
