Definition rlp_field_ref
(source : ByteSlice) (is_list : bool) (full_off : byte_quantity) (full_len : byte_quantity)
(content_off : byte_quantity) (content_len : byte_quantity)
: RlpFieldRef :=
   {| RlpFieldRef_source := source;
      RlpFieldRef_is_list := is_list;
      RlpFieldRef_full_off := full_off;
      RlpFieldRef_full_len := full_len;
      RlpFieldRef_content_off := content_off;
      RlpFieldRef_content_len := content_len |}.

Definition rlp_invalid_cursor (source : ByteSlice) : RlpCursor :=
   {| RlpCursor_source := source;
      RlpCursor_current := BYTE_ZERO;
      RlpCursor_stop := BYTE_ZERO;
      RlpCursor_valid := false |}.

Definition rlp_node_cursor (node : ByteSlice) : M (RlpCursor) :=
   let n := node.(ByteSlice_len) in
   (if byte_quantity_equal (n) (BYTE_ZERO) then returnM ((rlp_invalid_cursor (node)))
    else
      (rlp_ref_hdr (node) (BYTE_ZERO) (n)) >>= fun '((is_list, content, content_len)) =>
      (rlp_checked_add_quantity (content) (content_len)) >>= fun content_stop =>
      returnM ((if andb (is_list) ((byte_quantity_equal (content_stop) (n))) then
                  {| RlpCursor_source := node;
                     RlpCursor_current := content;
                     RlpCursor_stop := content_stop;
                     RlpCursor_valid := true |}
                else rlp_invalid_cursor (node))))
    : M (RlpCursor).

Definition rlp_ref_cursor (f : RlpFieldRef) : M (RlpCursor) :=
   (if f.(RlpFieldRef_is_list) return M (RlpCursor) then
      (rlp_checked_add_quantity (f.(RlpFieldRef_content_off)) (f.(RlpFieldRef_content_len))) >>= fun stop =>
      returnM (({| RlpCursor_source := f.(RlpFieldRef_source);
                   RlpCursor_current := f.(RlpFieldRef_content_off);
                   RlpCursor_stop := stop;
                   RlpCursor_valid := true |}))
    else throw (InvalidBlock (RlpDecode)))
    : M (RlpCursor).

Definition rlp_cursor_empty (cursor : RlpCursor) : bool :=
   andb (cursor.(RlpCursor_valid))
     ((byte_quantity_equal (cursor.(RlpCursor_current)) (cursor.(RlpCursor_stop)))).

Definition rlp_cursor_pop (cursor : RlpCursor) : M ((RlpFieldRef * RlpCursor)) :=
   let current : byte_quantity := cursor.(RlpCursor_current) in
   let stop : byte_quantity := cursor.(RlpCursor_stop) in
   (if orb ((negb (cursor.(RlpCursor_valid)))) ((negb ((byte_quantity_lt (current) (stop)))))
      return
      M (unit) then
      throw (InvalidBlock (RlpDecode))
    else returnM (tt)) >>
   (rlp_ref_hdr (cursor.(RlpCursor_source)) (current) (stop)) >>= fun '((is_list, content, content_len)) =>
   (rlp_checked_add_quantity (content) (content_len)) >>= fun next =>
   (if byte_quantity_lt (stop) (next) return M (unit) then throw (InvalidBlock (RlpDecode))
    else returnM (tt)) >>
   (if byte_quantity_le (current) (next) return M ((RlpFieldRef * RlpCursor)) then
      (byte_quantity_sub (next) (current)) >>= fun (full_len : byte_quantity) =>
      returnM ((rlp_field_ref (cursor.(RlpCursor_source)) (is_list) (current) (full_len) (content)
                  (content_len), {| RlpCursor_source := cursor.(RlpCursor_source);
                                    RlpCursor_current := next;
                                    RlpCursor_stop := stop;
                                    RlpCursor_valid := true |}))
    else throw (InvalidBlock (RlpDecode)))
    : M ((RlpFieldRef * RlpCursor)).

Definition rlp_cursor_expect_end (cursor : RlpCursor) : M (unit) :=
   (if rlp_cursor_empty (cursor) then returnM (tt)
    else throw (InvalidBlock (RlpDecode)))
    : M (unit).

Definition rlp_single_ref (item : ByteSlice) : M (RlpFieldRef) :=
