      (rlp_checked_add_quantity (cs) (cl)) >>= fun len =>
      (if byte_quantity_not_equal (len) (item_len) return M (unit) then
         throw (InvalidBlock (RlpDecode))
       else returnM (tt)) >>
      returnM ((rlp_field_ref (item) (isl) (BYTE_ZERO) (len) (cs) (cl))))
    : M (RlpFieldRef).

Definition rlp_ref_content (f : RlpFieldRef) : M (ByteSlice) :=
   (sub_slice (f.(RlpFieldRef_source)) (f.(RlpFieldRef_content_off)) (f.(RlpFieldRef_content_len)))
    : M (ByteSlice).

Definition rlp_ref_full (f : RlpFieldRef) : M (ByteSlice) :=
   (sub_slice (f.(RlpFieldRef_source)) (f.(RlpFieldRef_full_off)) (f.(RlpFieldRef_full_len)))
    : M (ByteSlice).

Definition rlp_ref_framing_canonical (f : RlpFieldRef) : M (bool) :=
   let n := f.(RlpFieldRef_content_len) in
   let fl := f.(RlpFieldRef_full_len) in
   let fo := f.(RlpFieldRef_full_off) in
   let co := f.(RlpFieldRef_content_off) in
