         let '((len_bytes, length_width)) := minimal_word_bytes (w__3) in
         (rlp_checked_add_quantity ((ByteQuantity ((Z.add (1) (length_width))))) (n)) >>= fun encoded_len =>
         (and_boolM (returnM (((byte_quantity_equal (fl) (encoded_len))  : bool)))
            ((and_boolM
