   (code_db_read_delegation (h)) >>= fun (r : mword 168) =>
   returnM ((eq_vec ((access_vec_dec (r) (160))) (('b"1")), subrange_vec_dec (r) (159) (0))).

Definition k_get_code_size (a : mword 160) : M (byte_length) :=
