Definition account_deleted_at_tx_end (acc : Account) : M (bool) :=
   (and_boolM (returnM ((acc.(Account_selfdestructed)  : bool)))
      ((or_boolM
          (read_reg k_fork >>= fun (w__0 : Fork) => returnM (((fork_lt (w__0) (Cancun))  : bool)))
          (returnM ((acc.(Account_created)  : bool))))
       : M (bool)))
    : M (bool).

Definition k_tx_merge '(tt : unit) : M (unit) :=
   let more : bool := true in
   (whileMT
     more
     (fun more => pow2 (64))
     (fun more => returnM (more))
     (fun more =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        (acct_tx_pop_ascending (tt)) >>= fun (w__0 : option AcctEntry) =>
        match w__0 with
        | Some e =>
           let curr : Account := e.(AcctEntry_value).(AcctValue_curr) in
           (account_deleted_at_tx_end (curr)) >>= fun deleted =>
           (if deleted return M (Account) then
              (k_emit_burn_log (e.(AcctEntry_addr)) (curr.(Account_info).(AccountInfo_balance))) >>
              let curr : Account := account_delete (curr) in
              returnM (curr)
            else returnM (curr)) >>= fun (curr : Account) =>
           (if orb (deleted)
                 ((andb (curr.(Account_storage_cleared))
                     ((negb (e.(AcctEntry_value).(AcctValue_orig).(Account_storage_cleared))))))
              return
              M (unit) then
              (storage_block_clear (e.(AcctEntry_addr)))
               : M (unit)
            else returnM (tt)) >>
           (if neq_int ((curr.(Account_info).(AccountInfo_nonce)).(protocol_quantity_value))
                 ((e.(AcctEntry_value).(AcctValue_orig).(Account_info).(AccountInfo_nonce)).(protocol_quantity_value))
              return
              M (unit) then
              (bal_nonce_change (e.(AcctEntry_addr))
                 (Build_protocol_quantity (((curr.(Account_info).(AccountInfo_nonce)).(protocol_quantity_value)))))
               : M (unit)
            else returnM (tt)) >>
           (if neq_vec (curr.(Account_info).(AccountInfo_balance))
                 (e.(AcctEntry_value).(AcctValue_orig).(Account_info).(AccountInfo_balance))
              return
              M (unit) then
              (bal_balance_change (e.(AcctEntry_addr)) (curr.(Account_info).(AccountInfo_balance)))
               : M (unit)
            else returnM (tt)) >>
           (if neq_vec (curr.(Account_info).(AccountInfo_code_hash))
                 (e.(AcctEntry_value).(AcctValue_orig).(Account_info).(AccountInfo_code_hash))
              return
              M (unit) then
              (bal_code_change (e.(AcctEntry_addr)) (curr.(Account_info).(AccountInfo_code_hash)))
               : M (unit)
            else returnM (tt)) >>
           let curr : Account :=
             {| Account_info := curr.(Account_info);
                Account_present := curr.(Account_present);
                Account_storage_cleared := curr.(Account_storage_cleared);
                Account_created := false;
                Account_selfdestructed := false |} in
           (if account_changed (curr) (e.(AcctEntry_value).(AcctValue_orig)) return M (unit) then
              (acct_block_write
                 (({| AcctEntry_addr := e.(AcctEntry_addr);
                      AcctEntry_value :=
                        {| AcctValue_curr := curr;
                           AcctValue_orig := e.(AcctEntry_value).(AcctValue_orig) |} |})))
               : M (unit)
            else returnM (tt)) >>
           returnM (more)
        | None => returnM (false)
        end
         : M (bool))
        : M (bool))) >>= fun (more : bool) =>
   let more : bool := true in
   (whileMT
     more
     (fun more => pow2 (64))
     (fun more => returnM (more))
     (fun more =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        (storage_tx_pop (tt)) >>= fun (w__1 : option StorageEntry) =>
        match w__1 with
        | Some e =>
           (acct_block_get (e.(StorageEntry_key).(StorageKey_addr))) >>= fun (w__2 : option Account) =>
           match w__2 with
           | Some acc =>
              (if andb (acc.(Account_present))
                    ((neq_vec (e.(StorageEntry_value).(StorageValue_curr))
                        (e.(StorageEntry_value).(StorageValue_orig))))
                 return
                 M (unit) then
                 (bal_storage_change (e.(StorageEntry_key).(StorageKey_addr))
                    (e.(StorageEntry_key).(StorageKey_slot))
                    (e.(StorageEntry_value).(StorageValue_curr))) >>
                 (storage_block_put (e))
                  : M (unit)
               else returnM (tt))
               : M (unit)
           | None => returnM (tt)
           end >>
           returnM (more)
        | None => returnM (false)
        end
         : M (bool))
        : M (bool))) >>= fun (more : bool) =>
   (acct_tx_reset (tt)) >> (storage_tx_reset (tt))  : M (unit).

