Definition scaled_blob_next
(term : ScaledBlobValue) (numerator : blob_gas_typ) (denominator : blob_fee_update_fraction)
(iteration : item_index) (*(0 <=? numerator) && (numerator <=? (2 ^ 64 - 1))*)
