   catch_early_return
     (liftR ((word_of_nat ((term.(ScaledBlobValue_remainder)).(protocol_quantity_value)))) >>= fun (w__0 : mword 256) =>
     liftR ((word_of_nat (numerator))) >>= fun (w__1 : mword 256) =>
