         returnM (semanticResult).(protocol_quantity_value)) >>= fun (w__5 : Z) =>
        let i := w__5  : Z in
        returnM ((i, output, term)))
        : M ((Z * ScaledBlobValue * ScaledBlobValue)))) >>= fun '((i, output, term)
   : (Z * ScaledBlobValue * ScaledBlobValue)) =>
