      returnM (None)
    else if andb ((negb (osaka))) ((andb ((word_is_zero (bl_word))) ((word_is_zero (ml_word)))))
    then
      returnM ((Some ((GasCost (200)))))
    else
      let maxlen := if Z.ltb (ml) (bl) then bl else ml in
      (exact_quotient ((Z.add (maxlen) (7))) (8)) >>= fun words =>
      let words_squared := Z.mul (words) (words) in
      let mult : Z :=
        if andb (osaka) ((Z.leb (maxlen) (32))) then 16
        else if osaka then Z.mul (2) (words_squared)
        else words_squared in
      let big_mul : Z := if osaka then 16 else 8 in
      let exp_off := Z.add (96) (bl) in
      (if Z.leb (el) (32) return M (Z) then
         (pc_word (input) (exp_off) (el)) >>= fun (w__1 : mword 256) =>
         let exponent_bits := (word_bit_length (w__1)).(word_bit_count_value) in
         returnM ((if Z.eqb (exponent_bits) (0) then 1
                   else
                     let count := Z.sub (exponent_bits) (1) in
                     if Z.eqb (count) (0) then 1
                     else count))
       else
         (pc_word (input) (exp_off) (32)) >>= fun (w__2 : mword 256) =>
         let head_bits := (word_bit_length (w__2)).(word_bit_count_value) in
         let high_bits := if neq_int (head_bits) (0) then Z.sub (head_bits) (1) else 0 in
         let count := Z.add ((Z.mul (big_mul) ((Z.sub (el) (32))))) (high_bits) in
         returnM ((if Z.eqb (count) (0) then 1 else count))) >>= fun (iterations : Z) =>
      (if osaka then returnM ((Z.mul (mult) (iterations)))
       else (exact_quotient ((Z.mul (mult) (iterations))) (3))  : M (Z)) >>= fun (calculated : Z) =>
      let minimum : Z := if osaka then 500 else 200 in
      returnM ((Some ((GasCost ((if Z.ltb (calculated) (minimum) then minimum else calculated)))))))
    : M (option gas_cost).

