Definition precompile_success (output : ByteSlice) : PrecompileResult :=
   {| PrecompileResult_success := true;  PrecompileResult_output := output |}.

Definition precompile_failure '(tt : unit) : PrecompileResult :=
   {| PrecompileResult_success := false;  PrecompileResult_output := EMPTY_SLICE |}.

Definition accelerator_result (success : bool) (output_len : byte_quantity) : PrecompileResult :=
   if success then precompile_success ((output_buffer_slice (output_len)))
   else precompile_failure (tt).

Definition copied_result (data : ByteSlice) : M (PrecompileResult) :=
   (freeze_output (data)) >>= fun output =>
   returnM ((if byte_quantity_equal (output.(ByteSlice_len)) (data.(ByteSlice_len)) then
               precompile_success (output)
             else precompile_failure (tt))).

Definition boolean_result (value : bool) : M (PrecompileResult) :=
   (output_buffer_word ((if value then WORD_ONE else WORD_ZERO))) >>= fun (w__0 : ByteSlice) =>
   returnM ((precompile_success (w__0))).

Definition is_precompile (n : precompile_id) (*(1 <=? n) && (n <=? 256)*) : M (bool) :=
   let n := (n).(precompile_id_value) in
   let base := Z.leb (n) (4) in
   (and_boolM (returnM ((Z.leb (5) (n))))
      (and_boolM (returnM ((Z.leb (n) (8))))
         (read_reg k_fork >>= fun (w__0 : Fork) =>
          returnM (((fork_gteq (w__0) (Byzantium))  : bool))))) >>= fun byzantium =>
   (and_boolM (returnM ((Z.eqb (n) (9))))
      (read_reg k_fork >>= fun (w__2 : Fork) => returnM (((fork_gteq (w__2) (Istanbul))  : bool)))) >>= fun istanbul =>
   (and_boolM (returnM ((Z.eqb (n) (10))))
      (read_reg k_fork >>= fun (w__3 : Fork) => returnM (((fork_gteq (w__3) (Cancun))  : bool)))) >>= fun kzg =>
   (and_boolM (returnM ((Z.leb (11) (n))))
      (and_boolM (returnM ((Z.leb (n) (17))))
         (read_reg k_fork >>= fun (w__4 : Fork) => returnM (((fork_gteq (w__4) (Prague))  : bool))))) >>= fun bls =>
   (and_boolM (returnM ((Z.eqb (n) (256))))
      (read_reg k_fork >>= fun (w__6 : Fork) => returnM (((fork_gteq (w__6) (Osaka))  : bool)))) >>= fun p256 =>
   returnM ((orb (base) ((orb (byzantium) ((orb (istanbul) ((orb (kzg) ((orb (bls) (p256))))))))))).

Definition run_ecrecover (input : ByteSlice) : M (PrecompileResult) :=
   (slice_load (input) (PRECOMPILE_WORD_LENGTH)) >>= fun v =>
   (or_boolM
      ((word_of_nat (27)) >>= fun (w__0 : mword 256) => returnM (((eq_vec (v) (w__0))  : bool)))
      ((word_of_nat (28)) >>= fun (w__1 : mword 256) => returnM (((eq_vec (v) (w__1))  : bool)))) >>= fun valid_v =>
   (if valid_v return M (PrecompileResult) then
      (word_of_nat (27)) >>= fun (w__2 : mword 256) =>
      let parity : Z := if eq_vec (v) (w__2) then 0 else 1 in
      (slice_load (input) (BYTE_ZERO)) >>= fun (w__3 : mword 256) =>
      (slice_load (input) (PRECOMPILE_DOUBLE_WORD_LENGTH)) >>= fun (w__4 : mword 256) =>
      (slice_load (input) (ECRECOVER_S_OFFSET)) >>= fun (w__5 : mword 256) =>
      (ecrecover_addr (w__3) (Build_y_parity ((parity))) (w__4) (w__5)) >>= fun '((recovered, address)) =>
      (if recovered return M (PrecompileResult) then
         (output_buffer_word ((address_to_word (address)))) >>= fun (w__6 : ByteSlice) =>
         returnM ((precompile_success (w__6)))
       else returnM ((precompile_success (EMPTY_SLICE))))
       : M (PrecompileResult)
    else returnM ((precompile_success (EMPTY_SLICE))))
    : M (PrecompileResult).

