            let refund := (gas_cost_to_refund (w__4))  : gas_refund in
            returnM (refund)
          else returnM (refund))
          : M (gas_refund)
       else returnM (refund))
       : M (gas_refund)
    else returnM (refund))
    : M (gas_refund).

Fixpoint process_auth_list (xs : list Authorization) : M (gas_refund) :=
