          (tx.(Transaction_sig_r)) (tx.(Transaction_sig_s)))
       : M (bool))) >>= fun (w__3 : bool) =>
   (if negb (w__3) return M (unit) then throw (InvalidBlock (InvalidSignature))
    else returnM (tt)) >>
   read_reg k_header >>= fun (w__4 : BlockHeader) =>
   let '((eff_gas_price, eff_priority_fee)) :=
     eff_gas_price_for (w__4.(BlockHeader_base_fee)) (tx.(Transaction_max_fee))
       (tx.(Transaction_max_priority_fee)) in
   let sender := tx.(Transaction_sender) in
   let '((ByteQuantity input_len)) := tx.(Transaction_input_src).(ByteSlice_len) in
   ((k_get_nonce (sender)) >>= fun semanticResult =>
    returnM (semanticResult).(protocol_quantity_value)) >>= fun nonce_before =>
   read_reg k_header >>= fun (w__5 : BlockHeader) =>
   (blob_base_fee
      (Build_protocol_quantity (((w__5.(BlockHeader_excess_blob_gas)).(protocol_quantity_value))))) >>= fun blob_price =>
   (transaction_costs (tx) (blob_price)) >>= fun checked_costs =>
   let costs_valid : bool := match checked_costs with | Some _ => true | None => false end in
   let costs : TransactionCosts :=
     match checked_costs with
     | Some costs => costs
     | None =>
        {| TransactionCosts_intrinsic := GAS_COST_ZERO;
           TransactionCosts_calldata_floor := GAS_COST_ZERO;
           TransactionCosts_blob_gas := (Build_protocol_quantity (0));
           TransactionCosts_blob_fee := ZERO_WORD;
           TransactionCosts_upfront := ZERO_WORD |}
     end in
   let nonce_ok : bool :=
     match (option_map (fun semanticValue => (semanticValue).(protocol_quantity_value)) (word_to_account_nonce
                                                                                           (tx.(Transaction_nonce)))) with
     | Some nonce => Z.eqb (nonce) (nonce_before)
     | None => false
     end in
   (k_deleg_target (sender)) >>= fun '((sender_deleg, _)) =>
   read_reg k_fork >>= fun (w__6 : Fork) =>
   (if fork_gteq (w__6) (Osaka) then returnM (6)
    else
      read_reg k_fork >>= fun (w__7 : Fork) =>
      let w__8 : Z := if fork_gteq (w__7) (Prague) then 9 else 6 in
      returnM (w__8)) >>= fun (max_blobs : Z) =>
   (if tx_is_blob (tx.(Transaction_tx_type)) return M (bool) then
      (and_boolM
         (read_reg k_fork >>= fun (w__9 : Fork) => returnM (((fork_gteq (w__9) (Cancun))  : bool)))
         (((and_boolM
              (returnM (((neq_int
                            ((tx.(Transaction_blob_hashes).(BlobHashes_count)).(protocol_quantity_value))
                            (0))
                : bool)))
              ((and_boolM
                  (returnM ((Z.leb
                               ((tx.(Transaction_blob_hashes).(BlobHashes_count)).(protocol_quantity_value))
                               (max_blobs))))
                  ((and_boolM (returnM (((negb (tx.(Transaction_is_create)))  : bool)))
                      ((blob_hashes_versioned (tx.(Transaction_blob_hashes)))
                       : M (bool)))
                   : M (bool)))
               : M (bool)))
          : M (bool))
          : M (bool)))
       : M (bool)
    else returnM (true)) >>= fun (blob_ok : bool) =>
   (or_boolM
      (read_reg k_fork >>= fun (w__15 : Fork) => returnM (((fork_lt (w__15) (Prague))  : bool)))
      (returnM (((gas_cost_le_gas (costs.(TransactionCosts_calldata_floor))
                    (tx.(Transaction_gas_limit)))
        : bool)))) >>= fun (floor_ok : bool) =>
   match tx.(Transaction_tx_type) with
   | LegacyTx => returnM (true)
   | _ =>
      read_reg k_chain_id >>= fun (w__16 : Z) =>
      returnM ((Z.eqb ((tx.(Transaction_chain_id)).(protocol_quantity_value)) (w__16)))
   end >>= fun (chain_id_ok : bool) =>
   (k_get_balance (sender)) >>= fun (w__17 : mword 256) =>
   let balance_ok : bool := word_ule (costs.(TransactionCosts_upfront)) (w__17) in
   (or_boolM
      ((k_code_key (sender)) >>= fun (w__18 : mword 256) =>
       returnM (((eq_vec (w__18) (KECCAK_EMPTY))  : bool))) (returnM (sender_deleg))) >>= fun (sender_code_ok : bool) =>
   let intrinsic_ok : bool :=
     gas_cost_le_gas (costs.(TransactionCosts_intrinsic)) (tx.(Transaction_gas_limit)) in
   read_reg k_header >>= fun (w__19 : BlockHeader) =>
   let fee_cap_ok : bool := word_ule (w__19.(BlockHeader_base_fee)) (tx.(Transaction_max_fee)) in
   let blob_fee_cap_ok : bool :=
     orb ((Z.eqb ((tx.(Transaction_blob_hashes).(BlobHashes_count)).(protocol_quantity_value)) (0)))
       ((word_ule (blob_price) (tx.(Transaction_max_blob_fee)))) in
   (or_boolM (returnM (((negb (tx.(Transaction_is_create)))  : bool)))
      ((initcode_size_allowed (input_len))
       : M (bool))) >>= fun (initcode_ok : bool) =>
   let priority_fee_ok : bool :=
     word_ule (tx.(Transaction_max_priority_fee)) (tx.(Transaction_max_fee)) in
   (or_boolM (returnM (((negb ((tx_is_access_list (tx.(Transaction_tx_type)))))  : bool)))
      (read_reg k_fork >>= fun (w__21 : Fork) => returnM (((fork_gteq (w__21) (Berlin))  : bool)))) >>= fun (access_list_fork_ok : bool) =>
   (or_boolM (returnM (((negb ((tx_is_dynamic_fee (tx.(Transaction_tx_type)))))  : bool)))
      (read_reg k_fork >>= fun (w__22 : Fork) => returnM (((fork_gteq (w__22) (London))  : bool)))) >>= fun (dynamic_fee_fork_ok : bool) =>
   let set_code_target_ok : bool :=
     orb ((negb ((tx_is_set_code (tx.(Transaction_tx_type))))))
       ((negb (tx.(Transaction_is_create)))) in
   let set_code_authorizations_ok : bool :=
     orb ((negb ((tx_is_set_code (tx.(Transaction_tx_type))))))
       (((neq_int ((tx.(Transaction_authorization_count)).(protocol_quantity_value)) (0))
        : bool)) in
   (or_boolM (returnM (((negb ((tx_is_set_code (tx.(Transaction_tx_type)))))  : bool)))
      (read_reg k_fork >>= fun (w__23 : Fork) => returnM (((fork_gteq (w__23) (Prague))  : bool)))) >>= fun (set_code_fork_ok : bool) =>
   let nonce_incrementable : bool := neq_int (nonce_before) ((Z.sub ((pow2 (64))) (1))) in
   read_reg k_header >>= fun (w__24 : BlockHeader) =>
   let block_gas_ok : bool := gas_le (tx.(Transaction_gas_limit)) (w__24.(BlockHeader_gas_limit)) in
   let valid :=
     andb (costs_valid)
       ((andb (balance_ok)
           ((andb (sender_code_ok)
               ((andb (intrinsic_ok)
                   ((andb (floor_ok)
                       ((andb (fee_cap_ok)
                           ((andb (blob_fee_cap_ok)
                               ((andb (blob_ok)
                                   ((andb (initcode_ok)
                                       ((andb (priority_fee_ok)
                                           ((andb (access_list_fork_ok)
                                               ((andb (dynamic_fee_fork_ok)
                                                   ((andb (set_code_target_ok)
                                                       ((andb (set_code_authorizations_ok)
                                                           ((andb (set_code_fork_ok)
                                                               ((andb (chain_id_ok)
                                                                   ((andb (nonce_ok)
                                                                       ((andb (nonce_incrementable)
                                                                           (block_gas_ok))))))))))))))))))))))))))))))))))) in
   returnM (({| TxValidity_valid := valid;
                TxValidity_sender := sender;
                TxValidity_nonce_before := (Build_protocol_quantity (nonce_before));
                TxValidity_intrinsic_gas := costs.(TransactionCosts_intrinsic);
                TxValidity_calldata_floor := costs.(TransactionCosts_calldata_floor);
                TxValidity_blob_fee := costs.(TransactionCosts_blob_fee);
                TxValidity_gas_price := eff_gas_price;
                TxValidity_priority_fee := eff_priority_fee |})).

Definition apply_transaction_upfront_effects (tx : Transaction) (v : TxValidity) : M (gas_refund) :=
   (validated_word_product (v.(TxValidity_gas_price)) (tx.(Transaction_gas_limit))) >>= fun (w__0 : mword 256) =>
   (k_sub_balance (v.(TxValidity_sender)) (w__0)) >>
   (if word_nonzero (v.(TxValidity_blob_fee)) return M (unit) then
      (k_sub_balance (v.(TxValidity_sender)) (v.(TxValidity_blob_fee)))
       : M (unit)
    else returnM (tt)) >>
   (k_bump_nonce (v.(TxValidity_sender))) >>
   (prewarm (tx)) >> (process_auth_list (tx.(Transaction_authorizations)))  : M (gas_refund).

Definition enter_transaction_frame (tx : Transaction) (intrinsic : gas_cost) : M (unit) :=
   write_reg pc BYTE_ZERO >>
   write_reg call_depth 0 >>
   (validated_gas_sub_cost (tx.(Transaction_gas_limit)) (intrinsic)) >>= fun (w__0 : gas) =>
   write_reg gas_remaining w__0 >>
   (stack_reset (tt)) >>
   (memory_reset (tt)) >>
   (returndata_clear (tt)) >>
   write_reg calldata EMPTY_SLICE >>
   write_reg frame_code EMPTY_CODE >>
   write_reg frame_refund GAS_REFUND_ZERO >> write_reg frame_status (Running (tt))  : M (unit).

Definition run_create_transaction_frame
(tx : Transaction) (sender : mword 160) (nonce_before : account_nonce)
(*(0 <=? nonce_before) && (nonce_before <=? (2 ^ 64 - 1))*)
: M (unit) :=
   let nonce_before := (nonce_before).(protocol_quantity_value) in
   (k_create_addr (sender) (Build_protocol_quantity ((nonce_before)))) >>= fun new_addr =>
   (k_access_account (new_addr)) >>= fun '(_) =>
   (k_account_occupied (new_addr)) >>= fun (w__0 : bool) =>
   (if w__0 return M (unit) then (exc_halt (AddressCollision))  : M (unit)
    else
      (k_mark_created (new_addr)) >>
      (k_clear_storage (new_addr)) >>
      (k_bump_nonce (new_addr)) >>
      (if word_nonzero (tx.(Transaction_value)) return M (unit) then
         (k_transfer (sender) (new_addr) (tx.(Transaction_value)))
          : M (unit)
       else returnM (tt)) >>
      write_reg
        message
        ({| Message_caller := sender;
            Message_address := new_addr;
            Message_code_address := new_addr;
            Message_value := tx.(Transaction_value);
            Message_is_static := false;
            Message_depth := (Build_frame_depth (0)) |}) >>
      (code_db_insert (tx.(Transaction_input_src))) >>= fun (w__1 : mword 256) =>
      (code_db_resolve (w__1)) >>= fun (w__2 : Code) =>
      write_reg frame_code w__2 >>
      (interpret (tt)) >>= fun deployed_code =>
      (frame_succeeded (tt)) >>= fun (w__3 : bool) =>
      (if w__3 return M (unit) then
         let dep_len := deployed_code.(ByteSlice_len) in
         (and_boolM
            ((max_code_size (tt)) >>= fun (w__4 : byte_quantity) =>
             returnM (((byte_quantity_le (dep_len) (w__4))  : bool)))
            ((or_boolM (returnM (((byte_quantity_equal (dep_len) (BYTE_ZERO))  : bool)))
                ((slice_byte (deployed_code) (BYTE_ZERO)) >>= fun (w__5 : mword 8) =>
                 returnM (((neq_vec (w__5) ((Ox"EF")))  : bool))))
             : M (bool))) >>= fun code_ok =>
         (if code_ok return M (unit) then
            let deposit := gas_constant_scale_byte_quantity (G_codedeposit) (dep_len) in
            read_reg gas_remaining >>= fun (w__7 : gas) =>
            (if gas_cost_le_gas (deposit) (w__7) return M (unit) then
               read_reg gas_remaining >>= fun (w__8 : gas) =>
               (gas_sub_cost_or_oog (w__8) (deposit)) >>= fun (w__9 : gas) =>
               write_reg gas_remaining w__9 >>
               (k_deploy_code (new_addr) (deployed_code))
                : M (unit)
             else (exc_halt (OutOfGas))  : M (unit))
             : M (unit)
          else (exc_halt (OutOfGas))  : M (unit))
          : M (unit)
       else returnM (tt))
       : M (unit))
    : M (unit).

Definition run_call_transaction_frame (tx : Transaction) (sender : mword 160) : M (unit) :=
   (k_aload (tx.(Transaction_recipient))) >>= fun '(_) =>
   (if word_nonzero (tx.(Transaction_value)) return M (unit) then
      (k_transfer (sender) (tx.(Transaction_recipient)) (tx.(Transaction_value)))
       : M (unit)
    else returnM (tt)) >>
   match (option_map (fun semanticValue => (semanticValue).(precompile_id_value)) (word_to_precompile_id
                                                                                     ((address_to_word
                                                                                         (tx.(Transaction_recipient)))))) with
   | Some number =>
      (is_precompile (Build_precompile_id ((number)))) >>= fun (w__0 : bool) =>
      let w__1 : option Z := if w__0 then Some (number) else None in
      returnM (w__1)
   | _ => returnM (None)
   end >>= fun (precompile : option Z) =>
   match precompile with
   | Some number =>
      (precompile_gas (Build_precompile_id ((number))) (tx.(Transaction_input_src))) >>= fun (w__2 : option gas_cost) =>
      match w__2 with
      | Some used =>
         read_reg gas_remaining >>= fun (w__3 : gas) =>
         (if gas_cost_le_gas (used) (w__3) return M (unit) then
            (run_precompile_slice (Build_precompile_id ((number))) (tx.(Transaction_input_src))) >>= fun result =>
            (if result.(PrecompileResult_success) return M (unit) then
               read_reg gas_remaining >>= fun (w__4 : gas) =>
               (gas_sub_cost_or_oog (w__4) (used)) >>= fun (w__5 : gas) =>
               write_reg gas_remaining w__5 >>
               (is_running (tt)) >>= fun (w__6 : bool) =>
               (if w__6 return M (unit) then
                  write_reg frame_status (Halted ((HaltReturn (result.(PrecompileResult_output)))))
                   : M (unit)
                else returnM (tt))
                : M (unit)
             else (exc_halt (OutOfGas))  : M (unit))
             : M (unit)
          else (exc_halt (OutOfGas))  : M (unit))
          : M (unit)
      | _ => (exc_halt (OutOfGas))  : M (unit)
      end
       : M (unit)
   | None =>
      write_reg calldata tx.(Transaction_input_src) >>
      write_reg
        message
        ({| Message_caller := sender;
            Message_address := tx.(Transaction_recipient);
            Message_code_address := tx.(Transaction_recipient);
            Message_value := tx.(Transaction_value);
            Message_is_static := false;
            Message_depth := (Build_frame_depth (0)) |}) >>
      (k_deleg_target (tx.(Transaction_recipient))) >>= fun '((tx_deleg, tx_dtgt)) =>
      (if tx_deleg return M (unit) then
         (k_access_account (tx_dtgt)) >>= fun '(_) =>
         (k_aload (tx_dtgt)) >>= fun '(_) => returnM (tt)
       else returnM (tt)) >>
      (executable_code (tx.(Transaction_recipient)) (tx_deleg) (tx_dtgt)) >>= fun (w__7 : Code) =>
      write_reg frame_code w__7 >> (interpret (tt)) >>= fun '(_) => returnM (tt)
   end
    : M (unit).

Definition run_transaction_frame (tx : Transaction) (v : TxValidity) : M (TxFrameResult) :=
   (k_state_checkpoint (tt)) >>= fun checkpoint =>
   (enter_transaction_frame (tx) (v.(TxValidity_intrinsic_gas))) >>
   (if tx.(Transaction_is_create) return M (unit) then
      (run_create_transaction_frame (tx) (v.(TxValidity_sender))
         (Build_protocol_quantity (((v.(TxValidity_nonce_before)).(protocol_quantity_value)))))
       : M (unit)
    else (run_call_transaction_frame (tx) (v.(TxValidity_sender)))  : M (unit)) >>
   (frame_succeeded (tt)) >>= fun success =>
   (if negb (success) return M (unit) then (k_revert (checkpoint))  : M (unit)
    else returnM (tt)) >>
   read_reg gas_remaining >>= fun (w__0 : gas) =>
   (if success return M (gas_refund) then read_reg frame_refund  : M (gas_refund)
    else returnM (GAS_REFUND_ZERO)) >>= fun (w__2 : gas_refund) =>
   returnM (({| TxFrameResult_success := success;
                TxFrameResult_gas_remaining := w__0;
                TxFrameResult_refund := w__2 |})).

Definition settle_transaction
(tx : Transaction) (v : TxValidity) (authorization_refund : gas_refund) (fr : TxFrameResult)
: M (Receipt) :=
   let gas_left0 := fr.(TxFrameResult_gas_remaining) in
   (validated_gas_sub_gas (tx.(Transaction_gas_limit)) (gas_left0)) >>= fun gas_used0 =>
   read_reg k_fork >>= fun (w__0 : Fork) =>
   let refund_quotient : Z := if fork_gteq (w__0) (London) then 5 else 2 in
   (gas_quotient (gas_used0) (Build_gas_divisor ((refund_quotient)))) >>= fun refund_cap =>
   let refund :=
     capped_gas_refund ((gas_refund_add (authorization_refund) (fr.(TxFrameResult_refund))))
       (refund_cap) in
   (validated_gas_add (gas_left0) (refund)) >>= fun gas_left1 =>
   (validated_gas_sub_gas (tx.(Transaction_gas_limit)) (gas_left1)) >>= fun gas_used1 =>
   read_reg k_fork >>= fun (w__1 : Fork) =>
   (if fork_gteq (w__1) (Prague) return M (gas) then
      let '((GasCost floor_cost)) := v.(TxValidity_calldata_floor) in
      let '((Gas tx_limit)) := tx.(Transaction_gas_limit) in
      (if Z.leb (floor_cost) (tx_limit) then returnM ((Gas (floor_cost)))
       else throw (InvalidBlock (ExecutionInvalid)))
       : M (gas)
    else returnM (GAS_ZERO)) >>= fun (floor : gas) =>
   let gas_used := if gas_lt (gas_used1) (floor) then floor else gas_used1 in
   (validated_gas_sub_gas (tx.(Transaction_gas_limit)) (gas_used)) >>= fun gas_left =>
   read_reg k_fork >>= fun (w__4 : Fork) =>
   let block_gas :=
     if fork_gteq (w__4) (Amsterdam) then if gas_lt (gas_used0) (floor) then floor else gas_used0
     else gas_used in
   (validated_word_product (v.(TxValidity_gas_price)) (gas_left)) >>= fun (w__5 : mword 256) =>
   (k_add_balance (v.(TxValidity_sender)) (w__5)) >>
   (k_coinbase (tt)) >>= fun (w__6 : mword 160) =>
   (validated_word_product (v.(TxValidity_priority_fee)) (gas_used)) >>= fun (w__7 : mword 256) =>
   (k_add_balance (w__6) (w__7)) >>
   (k_tx_merge (tt)) >>
   (read_logs (tt)) >>= fun (w__8 : list LogEntry) =>
   returnM (({| Receipt_tx_type := tx.(Transaction_tx_type);
                Receipt_success := fr.(TxFrameResult_success);
                Receipt_valid := true;
                Receipt_gas_used := gas_used;
                Receipt_block_gas := block_gas;
                Receipt_logs := w__8 |})).

Definition process_transaction (tx : Transaction) : M (Receipt) :=
   (k_tx_reset (tt)) >>
   (check_transaction_validity (tx)) >>= fun validity =>
   (if negb (validity.(TxValidity_valid)) then returnM ((invalid_receipt (tt)))
    else
      (k_set_tx
         (({| TxEnv_origin := tx.(Transaction_sender);
