         (field_to_ref (ext.(ExtensionNodeData_child))) >>= fun (w__6 : NodeRef) =>
         (extension_child_ref (w__5) (w__6))
          : M (NodeRef)
      | _ =>
         (node_to_ref (childnode)) >>= fun (w__8 : NodeRef) =>
         (extension_child_ref (prefix) (w__8))
          : M (NodeRef)
      end
