   (if Z.eqb (((path_len (prefix)).(trie_path_len_value))) (0) then returnM (childref)
    else
      match childref with
      | EmptyRef tt => returnM ((EmptyRef (tt)))
      | HashRef _ => (extension_child_ref (prefix) (childref))  : M (NodeRef)
      | InlineRef node =>
         (inline_node_slice (node)) >>= fun (w__1 : ByteSlice) =>
         (decode_trie_node (w__1)) >>= fun (w__2 : TrieNode) =>
         match w__2 with
         | LeafNode leaf =>
            (path_concat (prefix) (leaf.(LeafNodeData_path))) >>= fun (w__3 : TriePath) =>
            (rlp_ref_content (leaf.(LeafNodeData_value))) >>= fun (w__4 : ByteSlice) =>
            (leaf_child_ref (w__3) (w__4))
             : M (NodeRef)
         | ExtensionNode ext =>
            (path_concat (prefix) (ext.(ExtensionNodeData_path))) >>= fun (w__6 : TriePath) =>
            (field_to_ref (ext.(ExtensionNodeData_child))) >>= fun (w__7 : NodeRef) =>
            (extension_child_ref (w__6) (w__7))
             : M (NodeRef)
         | _ => (extension_child_ref (prefix) (childref))  : M (NodeRef)
