            : M (list TrieUpdate)
        | None => throw (InvalidBlock (WitnessDeficient))
        end >>= fun (updates : list TrieUpdate) =>
        returnM ((remaining, updates)))
        : M ((Z * list TrieUpdate)))) >>= fun '((remaining, updates)
   : (Z * list TrieUpdate)) =>
   returnM (updates).

Definition account_update (entry : AcctEntry) (storage : list TrieUpdate) : M (TrieUpdate) :=
