                 ((negb ((updates_empty (storage)))))
              return
              M (list TrieUpdate) then
              (account_update (entry) (storage)) >>= fun (w__2 : TrieUpdate) =>
              returnM (((w__2 :: accounts)  : list TrieUpdate))
            else returnM (accounts))
            : M (list TrieUpdate)
        | None => throw (InvalidBlock (WitnessDeficient))
        end >>= fun (accounts : list TrieUpdate) =>
        returnM ((accounts, remaining)))
        : M ((list TrieUpdate * Z)))) >>= fun '((accounts, remaining)
   : (list TrieUpdate * Z)) =>
   ((read_reg k_parent_state_root)  : M (mword 256)) >>= fun (w__3 : mword 256) =>
   (trie_root (w__3) (accounts))
    : M (mword 256).

