              ((slice_load (data) (DEPOSIT_WITHDRAWAL_CREDENTIALS_HEAD)) >>= fun (w__2 : mword 256) =>
               (word_of_nat (256)) >>= fun (w__3 : mword 256) =>
               returnM (((neq_vec (w__2) (w__3))  : bool)))
