                           : M (bool)))
                       : M (bool)))
                   : M (bool)))
               : M (bool)))
           : M (bool)))
       : M (bool))) >>= fun (w__29 : bool) =>
   (if w__29 return M (unit) then throw (InvalidBlock (InvalidExecutionRequests))
    else returnM (tt)) >>
   (sub_slice (data) (DEPOSIT_PUBKEY_DATA) (DEPOSIT_PUBKEY_LENGTH)) >>= fun (w__30 : ByteSlice) =>
   (scratch_push_slice (w__30)) >>
   (sub_slice (data) (DEPOSIT_WITHDRAWAL_CREDENTIALS_DATA) (DEPOSIT_WITHDRAWAL_CREDENTIALS_LENGTH)) >>= fun (w__31 : ByteSlice) =>
   (scratch_push_slice (w__31)) >>
