Definition validate_execution_payload
(input : StatelessInput) (input_ref : StatelessInputRef) (witness : WitnessContext)
: M (unit) :=
   let payload := input.(StatelessInput_payload) in
   let block := payload.(ExecutionPayload_block) in
   let header := block.(Block_header) in
   let body := block.(Block_body) in
   (if negb
         ((andb
             ((Z.leb (9)
                 ((input.(StatelessInput_chain_config).(ChainConfig_fork_index)).(protocol_quantity_value))))
             (((andb
                  ((Z.leb
                      ((input.(StatelessInput_chain_config).(ChainConfig_fork_index)).(protocol_quantity_value))
                      (20)))
                  ((andb (input.(StatelessInput_chain_config).(ChainConfig_activation_active))
                      ((chain_config_blob_schedule_valid (input.(StatelessInput_chain_config)))))))
              : bool))))
      return
      M (unit) then
      throw (InvalidBlock (InvalidConfig))
    else returnM (tt)) >>
   (if gas_lt (header.(BlockHeader_gas_limit)) (header.(BlockHeader_gas_used)) return M (unit) then
      throw (InvalidBlock (InvalidGasUsed))
    else returnM (tt)) >>
   (if neq_vec (witness.(WitnessContext_parent_hash)) (header.(BlockHeader_parent_hash))
      return
      M (unit) then
      throw (InvalidBlock (InvalidParentHash))
    else returnM (tt)) >>
   (and_boolM
      (read_reg k_fork >>= fun (w__0 : Fork) => returnM (((fork_gteq (w__0) (Cancun))  : bool)))
      (((expected_payload_excess_blob_gas (witness)) >>= fun semanticResult =>
        returnM (semanticResult).(protocol_quantity_value)) >>= fun (w__1 : Z) =>
       returnM (((neq_int ((header.(BlockHeader_excess_blob_gas)).(protocol_quantity_value)) (w__1))
        : bool)))) >>= fun (w__2 : bool) =>
   (if w__2 return M (unit) then throw (InvalidBlock (InvalidExcessBlobGas))
    else returnM (tt)) >>
   read_reg k_fork >>= fun (w__3 : Fork) =>
   (if fork_gteq (w__3) (Paris) return M (unit) then
      (transaction_trie_root (body.(BlockBody_transactions))) >>= fun transactions_root =>
      read_reg k_fork >>= fun (w__4 : Fork) =>
      (if fork_gteq (w__4) (Shanghai) return M (mword 256) then
         (withdrawals_trie_root (body.(BlockBody_withdrawals)))
          : M (mword 256)
       else returnM (EMPTY_TRIE_ROOT)) >>= fun withdrawals_root =>
      read_reg k_fork >>= fun (w__6 : Fork) =>
      (if fork_gteq (w__6) (Prague) return M (mword 256) then
         (execution_requests_hash (input_ref))
          : M (mword 256)
       else returnM (ZERO_WORD)) >>= fun requests_hash =>
      read_reg k_fork >>= fun (w__8 : Fork) =>
      (if fork_gteq (w__8) (Amsterdam) return M (mword 256) then
         (keccak256_slice (body.(BlockBody_block_access_list)))
          : M (mword 256)
       else returnM (ZERO_WORD)) >>= fun block_access_list_hash =>
      (block_header_hash (header) (transactions_root) (withdrawals_root) (requests_hash)
         (block_access_list_hash)) >>= fun computed_block_hash =>
      (if neq_vec (computed_block_hash) (payload.(ExecutionPayload_expected_block_hash))
         return
         M (unit) then
         throw (InvalidBlock (InvalidBlockHash))
       else returnM (tt))
       : M (unit)
    else returnM (tt))
    : M (unit).

Definition validate_executed_block
(block : Block) (input_ref : StatelessInputRef) (exec_ok : bool) (result : BlockExecutionResult)
: M (unit) :=
   let header := block.(Block_header) in
   let gas_used_ok :=
     gas_equal (result.(BlockExecutionResult_gas_acc)) (header.(BlockHeader_gas_used)) in
   (or_boolM
      (read_reg k_fork >>= fun (w__0 : Fork) => returnM (((fork_lt (w__0) (Cancun))  : bool)))
      (returnM (((Z.eqb ((result.(BlockExecutionResult_blob_gas_acc)).(protocol_quantity_value))
                    ((header.(BlockHeader_blob_gas_used)).(protocol_quantity_value)))
        : bool)))) >>= fun blob_gas_used_ok =>
   (compute_state_root (tt)) >>= fun (w__1 : mword 256) =>
   let poststate_ok := eq_vec (w__1) (header.(BlockHeader_state_root)) in
   let receipts_root_ok :=
     eq_vec (result.(BlockExecutionResult_receipts_root)) (header.(BlockHeader_receipts_root)) in
   let logs_bloom_ok :=
     logs_bloom_equal (result.(BlockExecutionResult_logs_bloom)) (header.(BlockHeader_logs_bloom)) in
   let block_access_list_size_ok : bool := true in
   let block_access_list_ok : bool := true in
   let execution_requests_ok : bool := true in
   read_reg k_fork >>= fun (w__2 : Fork) =>
   (if fork_gteq (w__2) (Prague) return M (bool) then
      (and_boolM
         ((bytes_segments_equal_slice
             ([BytesSlice (result.(BlockExecutionResult_requests).(ExecutionRequests_deposits))])
             (input_ref.(StatelessInputRef_deposits)))
          : M (bool))
         ((and_boolM
             ((bytes_segments_equal_slice
                 ([BytesSlice
                     (result.(BlockExecutionResult_requests).(ExecutionRequests_withdrawals))])
                 (input_ref.(StatelessInputRef_withdrawal_requests)))
              : M (bool))
             ((bytes_segments_equal_slice
                 ([BytesSlice
                     (result.(BlockExecutionResult_requests).(ExecutionRequests_consolidations))])
                 (input_ref.(StatelessInputRef_consolidation_requests)))
              : M (bool)))
          : M (bool)))
       : M (bool)
    else returnM (execution_requests_ok)) >>= fun (execution_requests_ok : bool) =>
   read_reg k_fork >>= fun (w__8 : Fork) =>
   (if fork_gteq (w__8) (Amsterdam) return M ((bool * bool)) then
      (encode_block_access_list (tt)) >>= fun block_access_list =>
      let '((Gas gas_limit)) := header.(BlockHeader_gas_limit) in
      (exact_quotient (gas_limit) (2000)) >>= fun maximum_items =>
      let block_access_list_size_ok : bool :=
        Z.leb ((block_access_list.(EncodedBlockAccessList_item_count)).(protocol_quantity_value))
          (maximum_items) in
      (bytes_segments_equal_slice ([BytesSlice (block_access_list.(EncodedBlockAccessList_bytes))])
         (block.(Block_body).(BlockBody_block_access_list))) >>= fun (w__9 : bool) =>
      let block_access_list_ok := w__9  : bool in
      returnM ((block_access_list_ok, block_access_list_size_ok))
    else returnM ((block_access_list_ok, block_access_list_size_ok))) >>= fun '((block_access_list_ok, block_access_list_size_ok)
   : (bool * bool)) =>
   (if result.(BlockExecutionResult_block_gas_overflow) return M (unit) then
      throw (InvalidBlock (GasUsedExceedsLimit))
    else returnM (tt)) >>
   (if result.(BlockExecutionResult_blob_gas_overflow) return M (unit) then
      throw (InvalidBlock (BlobGasLimitExceeded))
    else returnM (tt)) >>
   (if negb (exec_ok) return M (unit) then throw (InvalidBlock (ExecutionInvalid))
    else returnM (tt)) >>
   (if negb (execution_requests_ok) return M (unit) then
      throw (InvalidBlock (InvalidExecutionRequests))
    else returnM (tt)) >>
   (if negb (block_access_list_size_ok) return M (unit) then
      throw (InvalidBlock (BlockAccessListTooLarge))
    else returnM (tt)) >>
   (if negb (gas_used_ok) return M (unit) then throw (InvalidBlock (InvalidGasUsed))
    else returnM (tt)) >>
   (if negb (blob_gas_used_ok) return M (unit) then throw (InvalidBlock (InvalidBlobGasUsed))
    else returnM (tt)) >>
   (if negb (poststate_ok) return M (unit) then throw (InvalidBlock (InvalidStateRoot))
    else returnM (tt)) >>
   (if negb (receipts_root_ok) return M (unit) then throw (InvalidBlock (InvalidReceiptsRoot))
    else returnM (tt)) >>
   (if negb (logs_bloom_ok) return M (unit) then throw (InvalidBlock (InvalidLogsBloom))
    else returnM (tt)) >>
   (if negb (block_access_list_ok) return M (unit) then
      throw (InvalidBlock (InvalidBlockAccessList))
    else returnM (tt))
    : M (unit).

Definition undefined_StatelessValidationFailure '(tt : unit) : M (StatelessValidationFailure) :=
   (undefined_bitvector (8)) >>= fun (w__0 : mword 8) =>
